<script setup lang="ts">
const route=useRoute(),{data}=useCatalog()
const query=computed(()=>String(route.query.q||'').trim())
const matches=(v:string)=>v.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(query.value.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,''))
const artists=computed(()=>query.value?data.value.artists.filter(a=>matches(a.name)):[])
const albums=computed(()=>query.value?data.value.albums.filter(a=>matches(a.title)||matches(data.value.artists.find(x=>x.id===a.artistId)?.name||'')):[])
const tracks=computed(()=>query.value?data.value.tracks.filter(t=>matches(t.title)||matches(data.value.artists.find(a=>a.id===t.artistId)?.name||'')):[])
useSeoMeta({title:()=>query.value?'Buscar '+query.value+' | WEBMUSIC':'Buscar | WEBMUSIC',robots:'noindex,follow'})
</script>
<template><NuxtLayout><h1 class="mb-2 text-3xl font-extrabold">Resultados de búsqueda</h1><p class="mb-8 text-sm text-[#979bad]">Buscando: <strong class="text-violet-300">{{query||'Escribe una búsqueda'}}</strong></p><div v-if="artists.length" class="mb-9"><h2 class="mb-4 text-xl font-bold">Artistas</h2><div class="flex flex-wrap gap-3"><NuxtLink v-for="a in artists" :key="a.id" :to="'/artista/'+a.slug" class="flex items-center gap-3 rounded-xl bg-[#191c27] p-3 hover:bg-[#252838]"><img :src="a.cover" class="h-11 w-11 rounded-full object-cover" :alt="a.name"/>{{a.name}}</NuxtLink></div></div><div v-if="albums.length" class="mb-9"><h2 class="mb-4 text-xl font-bold">Álbumes</h2><div class="grid grid-cols-2 gap-4 sm:grid-cols-4 lg:grid-cols-5"><AlbumCard v-for="a in albums" :key="a.id" :album="a" :artist="data.artists.find(x=>x.id===a.artistId)" :tracks="data.tracks"/></div></div><div v-if="tracks.length"><h2 class="mb-4 text-xl font-bold">Canciones</h2><div class="rounded-xl bg-[#151822] p-2"><TrackRow v-for="(t,i) in tracks" :key="t.id" :track="t" :index="i" :artist="data.artists.find(a=>a.id===t.artistId)" :album="data.albums.find(a=>a.id===t.albumId)" :queue="tracks"/></div></div><div v-if="query&&!artists.length&&!albums.length&&!tracks.length" class="py-16 text-center text-[#999cad]">No encontramos resultados. Prueba con otro término.</div></NuxtLayout></template>
